import json, subprocess, warnings
warnings.filterwarnings("ignore")
from TTS.utils.synthesizer import Synthesizer
from hts_close import close_voice
lines = [
 "जोड़ों में दर्द और सूजन? धूप में चेहरे पर लाल चकत्ते? तो डॉक्टर ए एन ए टेस्ट लिख सकते हैं. यह क्या है, और आई एफ ए तरीका क्यों खास है? आखिर तक देखिए.",
 "कभी कभी हमारा इम्यून सिस्टम गलती से, हमारी ही कोशिकाओं के न्यूक्लियस के खिलाफ एंटीबॉडी बना देता है. इन्हें एंटीन्यूक्लियर एंटीबॉडी, यानी ए एन ए कहते हैं. ये ल्यूपस, यानी एस एल ई, स्जोग्रेन, और स्क्लेरोडर्मा जैसी ऑटोइम्यून बीमारियों में मिलती हैं.",
 "आई एफ ए में, मरीज़ का सीरम, हेप टू कोशिकाओं वाली स्लाइड पर डाला जाता है. ए एन ए हो, तो वह न्यूक्लियस से चिपक जाती है. फिर फ्लोरेसेंट रंग वाली एंटीबॉडी डाली जाती है, और खास माइक्रोस्कोप में न्यूक्लियस हरा चमकता है. अमेरिकन कॉलेज ऑफ रूमेटोलॉजी, इसे गोल्ड स्टैंडर्ड मानता है.",
 "सीरम को पतला करके, एक बटा चालीस, एक बटा अस्सी, एक बटा एक सौ साठ, ऐसे देखा जाता है. जिस सबसे ज़्यादा पतलेपन पर भी चमक दिखे, वह टाइटर है. टाइटर जितना ऊंचा, बीमारी की संभावना उतनी ज़्यादा.",
 "रिपोर्ट में पैटर्न भी लिखा होता है. होमोजीनियस, अक्सर एस एल ई में. स्पेकल्ड, कई ऑटोइम्यून बीमारियों में. सेंट्रोमियर, अक्सर लिमिटेड स्क्लेरोडर्मा में. न्यूक्लियोलर, सिस्टमिक स्क्लेरोसिस में. और डेंस फाइन स्पेकल्ड, अक्सर बिना ऑटोइम्यून बीमारी वाले लोगों में.",
 "डॉक्टर यह जांच कब कहते हैं? जोड़ों में सूजन के साथ दर्द. धूप से चेहरे पर चकत्ते. मुंह के छाले. ठंड में उंगलियां सफेद या नीली होना. आंख और मुंह का सूखापन. सिर्फ थकान या बदन दर्द में, आमतौर पर यह जांच ज़रूरी नहीं.",
 "पॉज़िटिव ए एन ए का मतलब, हमेशा बीमारी नहीं. अमेरिका के एक बड़े सर्वे में, बारह साल से ऊपर, लगभग चौदह प्रतिशत लोगों में ए एन ए पॉज़िटिव मिला. इन्फेक्शन और कुछ दवाओं से भी हो सकता है. पॉज़िटिव हो, तो डॉक्टर डबल स्ट्रैंडेड डी एन ए, या ई एन ए प्रोफाइल जैसी जांच करवा सकते हैं.",
 "तैयारी? आमतौर पर खाली पेट की ज़रूरत नहीं. जो दवाएं ले रहे हैं, ज़रूर बताएं. सिर्फ एक रिपोर्ट से डायग्नोसिस नहीं होता. बिना सलाह, बार बार यह जांच न करवाएं.",
 close_voice("क्या आपने कभी ए एन ए टेस्ट करवाया है?"),
]
import os
d = os.environ.get("HTS_MODEL", "/tmp/hi/hi/")
s = Synthesizer(tts_checkpoint=d + "fastpitch/best_model.pth", tts_config_path=d + "fastpitch/config.json",
                vocoder_checkpoint=d + "hifigan/best_model.pth", vocoder_config=d + "hifigan/config.json", use_cuda=False)
durs = []
for i, l in enumerate(lines):
    f = f"/tmp/anar_{i}.wav"; s.save_wav(s.tts(l, speaker_name="female"), f)
    subprocess.run(["ffmpeg","-nostdin","-y","-loglevel","error","-i",f,"-af","rubberband=pitch=0.96:formant=preserved,equalizer=f=250:t=q:w=1:g=2,treble=g=-1.5:f=6000",f"/tmp/ana_{i}.wav"],check=True); f=f"/tmp/ana_{i}.wav"
    durs.append(float(subprocess.check_output(["ffprobe", "-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0", f]).decode()))
json.dump(durs, open("/tmp/ana_durs.json", "w")); print([round(x, 1) for x in durs], round(sum(durs), 1))
